const item = $input.first().json;
const titulos = Array.isArray(item.titulos) ? item.titulos : [];
const enlaces = Array.isArray(item.enlaces) ? item.enlaces : [];
const resumenes = Array.isArray(item.resumenes) ? item.resumenes : [];

const hoy = new Date().toISOString().split('T')[0];
const resultados = [];
const urlsVistas = new Set();

for (let i = 0; i < titulos.length; i++) {
  const titulo = (titulos[i] || '').replace(/\s+/g, ' ').trim();
  const url = (enlaces[i] || '').trim();
  const resumen = (resumenes[i] || 'Novedad publicada en el portal oficial de noticias de la UNAB.').replace(/\s+/g, ' ').trim();

  if (!titulo || !url || !url.startsWith('http') || urlsVistas.has(url)) {
    continue;
  }

  urlsVistas.add(url);
  resultados.push({
    json: {
      titulo: titulo,
      url: url,
      resumen: resumen.slice(0, 500),
      fuente: 'Portal Noticias UNAB',
      fecha_publicacion: hoy
    }
  });

  if (resultados.length >= 10) break;
}

return resultados;
